mapper.select:
select id, product_id, product_name, product_desc, category, activity_id, original_price, group_price, image_url, badge, participant_count, status, sort_order from product_catalog where status = 1
and (product_name like concat('%', #{keyword}, '%') or product_desc like concat('%', #{keyword}, '%') or category like concat('%', #{keyword}, '%'))
and category = #{category}
and group_price <= #{maxPrice}
order by sort_order asc, id asc
